private static boolean isSteppingNumber(int num) {
    // Get the number as a string
    String strNum = String.valueOf(num);

    // Iterate through each digit
    for (int i = 0; i < strNum.length() - 1; i++) {
        // Get the current and next digits
        int currDigit = strNum.charAt(i) - '0';
        int nextDigit = strNum.charAt(i + 1) - '0';

        // Check if the digits are within 1 step of each other
        if (Math.abs(currDigit - nextDigit) != 1) {
            return false;
        }
    }

    // If all digits are within 1 step of each other, return true
    return true;
}

