    if (determinant > 0) {
        return false;
    }

    return true;
}

public static int crossProduct(int[] vector1, int[] vector2) {
    return vector1[0] * vector2[1] - vector1[1] * vector2[0];
}

public static int findNthUglyNumber(int n) {
  if (n <= 0) {
    throw new IllegalArgumentException("n must be positive.");
  }

  // Initialize the queue with the first 10 numbers.
  Queue<Integer> queue = new LinkedList<>();
  for (int i = 0; i < 10; i++) {
    queue.offer(i);
  }

  // Keep track of the number of elements in the queue and the first index.
  int count = 1;
  int first = 0;

  // Loop until we have enough elements in the queue.
  while (count < n) {
    // Get the first element in the queue.
    int current = queue.peek();

    // If the current element is a palindrome, we can remove it.
    if (current == String.valueOf(current).reverse().toString()) {
      queue.poll();
      count--;
    }

    // If the current element is not a palindrome, we need to add its mirror.
    else {
      queue.offer(String.valueOf(current).reverse().toString());
      count++;
    }
  }

  // Return the first nth element in the queue.
  return queue.peek();
}

public static int calculateEnergy(String s) {
    int max = 0;
    for (int i = 0; i < s.length(); i++) {
        int start = i;
        while (i < s.length() && s.charAt(i) == s.charAt(start)) {
            i++;
        }
        max = Math.max(max, i - start);
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
  List<Integer> result = new ArrayList<>();
  for (int i = 1; i <= n; i++) {
    result.add(i);
  }
  return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    for (int num : nums) {
        uniqueNums.add(num);
    }
    int sum = 0;
    for (int num : uniqueNums) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - (i * i);
        if (remainder == 0) {
            count++;
        } else {
            count += 2;
        }
    }
    return count;
}

public static String reverseWords(String s) {
    // Split the input string into an array of words
    String[] words = s.split(" ");

    // Initialize the output string with an empty string
    String output = "";

    // Loop through each word in the array
    for (String word : words) {
        // Initialize a new StringBuilder to store the reversed word
        StringBuilder reversedWord = new StringBuilder();

        // Loop through each character of the word
        for (int i = word.length() - 1; i >= 0; i--) {
            // Append the current character to the reversed word
            reversedWord.append(word.charAt(i));
        }

        // Append the reversed word to the output string, separated by a space
        output += reversedWord.toString() + " ";
    }

    // Return the output string with the reversed words
    return output.trim();
}
